package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchResult struct {
	ID       int
	Username string
	Email    string
	Role     string
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	term := r.URL.Query().Get("q")
	field := r.URL.Query().Get("field")

	if term == "" {
		http.Error(w, "Missing search term", 400)
		return
	}

	// Validate field parameter against allowed columns
	allowedFields := map[string]bool{
		"username": true,
		"email":    true,
		"role":     true,
	}

	if field == "" {
		field = "username"
	}

	if !allowedFields[field] {
		http.Error(w, "Invalid field", 400)
		return
	}

	// Build query - field is validated above but term is not parameterized
	// Developer assumed the LIKE pattern was safe since field is validated
	query := fmt.Sprintf(
		"SELECT id, username, email, role FROM users WHERE %s LIKE '%%%s%%' ORDER BY id LIMIT 50",
		field, term,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Username, &sr.Email, &sr.Role); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	var sb strings.Builder
	sb.WriteString("<html><body><h2>Search Results</h2><table>")
	sb.WriteString("<tr><th>ID</th><th>Username</th><th>Email</th><th>Role</th></tr>")
	for _, sr := range results {
		sb.WriteString(fmt.Sprintf(
			"<tr><td>%d</td><td>%s</td><td>%s</td><td>%s</td></tr>",
			sr.ID, sr.Username, sr.Email, sr.Role,
		))
	}
	sb.WriteString("</table></body></html>")
	w.Write([]byte(sb.String()))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
